CREATE TABLE webhook_endpoints(id TEXT PRIMARY KEY,namespace_id TEXT NOT NULL REFERENCES namespaces(id),url TEXT NOT NULL,secret_ref TEXT NOT NULL,key_id TEXT NOT NULL,UNIQUE(namespace_id,id));
CREATE TABLE triggers(id TEXT PRIMARY KEY,namespace_id TEXT NOT NULL,outcome_id TEXT NOT NULL,version BIGINT NOT NULL,enabled INTEGER NOT NULL,record_json TEXT NOT NULL,UNIQUE(namespace_id,outcome_id,id),FOREIGN KEY(namespace_id,outcome_id) REFERENCES outcomes(namespace_id,id));
CREATE INDEX trigger_scope ON triggers(namespace_id,outcome_id,enabled);
CREATE TABLE integration_events(id TEXT PRIMARY KEY,namespace_id TEXT NOT NULL,outcome_id TEXT NOT NULL,record_json TEXT NOT NULL,FOREIGN KEY(namespace_id,outcome_id) REFERENCES outcomes(namespace_id,id));
CREATE TABLE trigger_firings(id TEXT PRIMARY KEY,trigger_id TEXT NOT NULL REFERENCES triggers(id),trigger_version BIGINT NOT NULL,source_event_id TEXT NOT NULL REFERENCES integration_events(id),record_json TEXT NOT NULL,UNIQUE(trigger_id,trigger_version,source_event_id));
CREATE TABLE integration_deliveries(id TEXT PRIMARY KEY,namespace_id TEXT NOT NULL,outcome_id TEXT NOT NULL,integration_event_id TEXT NOT NULL REFERENCES trigger_firings(id),endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id),body_json TEXT NOT NULL,url TEXT NOT NULL,secret_ref TEXT NOT NULL,key_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','leased','succeeded','exhausted')),attempts BIGINT NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL,lease_id TEXT,lease_until BIGINT,fencing_token BIGINT NOT NULL DEFAULT 0,last_result TEXT NOT NULL DEFAULT '',UNIQUE(integration_event_id,endpoint_id),FOREIGN KEY(namespace_id,outcome_id) REFERENCES outcomes(namespace_id,id));
CREATE INDEX delivery_due ON integration_deliveries(status,next_attempt,lease_until);
CREATE TABLE delivery_attempts(delivery_id TEXT NOT NULL REFERENCES integration_deliveries(id),fencing_token BIGINT NOT NULL,lease_id TEXT NOT NULL,started_at BIGINT NOT NULL,finished_at BIGINT,result TEXT NOT NULL,PRIMARY KEY(delivery_id,fencing_token));
